def dihedral_orbit(grid,r,c):
    h,w=len(grid),len(grid[0])
    return [(r,c),(h-1-r,c),(r,w-1-c),(h-1-r,w-1-c),
            (c,r),(h-1-c,r),(c,w-1-r),(h-1-c,w-1-r)]
def dihedral_transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==2:
                for rr,cc in dihedral_orbit(grid,r,c):
                    if grid[rr][cc]!=2:
                        out[r][c]=grid[rr][cc]; break
    return out
